// Modelo de la VPC de la tienda: una subred pública con un servidor web.
// La NACL de la subred permite ahora el tráfico de retorno por los puertos efímeros.
export const vpc = {
  cidr: "10.0.0.0/16",
  subnets: [
    {
      id: "subnet-publica",
      cidr: "10.0.1.0/24",
      routes: [
        { destination: "10.0.0.0/16", target: "local" },
        { destination: "0.0.0.0/0", target: "igw-0a1b2c3d4e5f60718" },
      ],
      nacl: [
        { direction: "inbound", number: 100, action: "allow", protocol: "tcp", fromPort: 80, toPort: 80, cidr: "0.0.0.0/0" },
        { direction: "inbound", number: 110, action: "allow", protocol: "tcp", fromPort: 443, toPort: 443, cidr: "0.0.0.0/0" },
        { direction: "inbound", number: 120, action: "allow", protocol: "tcp", fromPort: 22, toPort: 22, cidr: "192.0.2.0/24" },
        { direction: "outbound", number: 100, action: "allow", protocol: "tcp", fromPort: 80, toPort: 80, cidr: "0.0.0.0/0" },
        { direction: "outbound", number: 110, action: "allow", protocol: "tcp", fromPort: 443, toPort: 443, cidr: "0.0.0.0/0" },
        { direction: "outbound", number: 140, action: "allow", protocol: "tcp", fromPort: 1024, toPort: 65535, cidr: "0.0.0.0/0" },
      ],
    },
  ],
  securityGroups: [
    {
      id: "sg-web",
      rules: [
        { direction: "inbound", protocol: "tcp", fromPort: 80, toPort: 80, cidr: "0.0.0.0/0" },
        { direction: "inbound", protocol: "tcp", fromPort: 443, toPort: 443, cidr: "0.0.0.0/0" },
        { direction: "inbound", protocol: "tcp", fromPort: 22, toPort: 22, cidr: "192.0.2.0/24" },
        { direction: "outbound", protocol: "-1", cidr: "0.0.0.0/0" },
      ],
    },
  ],
};

